#pragma once
// Double-precision world math (Vec3d, Quatd, Mat3d) that reproduces Apple's <simd/simd.h> bit-for-bit, as the
// Swift app calls it on arm64 (Sources/Core/Math.swift). Apple's headers compile with FP contraction ON, so some
// a*b+c expressions are fused; we write those as explicit std::fma (correctly rounded everywhere, so the result
// is the same on macOS, Windows/MSVC and any x86/arm CPU) and everything else unfused (-ffp-contract=off).
// Every function here is checked against cpp/tests/parity/simd.json (generated by cpp/tools/simd_reference.swift).
//
// Rules recovered from Apple's headers + the disassembly of libsystem_m (__invert_d3):
//   simd_dot(a,b)        (a.x*b.x + a.y*b.y) + a.z*b.z                      (vector mul, then reduce: no FMA)
//   simd_length          sqrt(dot)        simd_normalize  v * (1/sqrt(dot))
//   simd_cross           fma(x.y, y.z, -(x.z*y.y)), ...                      (clang fuses the LHS product)
//   quat * quat          fma(p.x, A, p.y*B) + fma(p.z, C, p.w*q)             (see quatMul)
//   simd_act (arm64)     q * (v * conj(q)) with the same fused pattern
//   simd_normalize(q)    q * (1/sqrt((x²+z²)+(y²+w²)))       simd_inverse(q)  conj(q) * (1/len²)
//   matrix * vector      c0*y.x, then fma(c1, y.y, r), fma(c2, y.z, r)
//   simd_inverse(3x3)    cofactors with fnmsub/fnmadd, det fused, then * (1/det)
// Craft frame: +X forward, +Y up, +Z right. World: right-handed, +Y up.
#include <cmath>

namespace pw {

constexpr double kPi = 3.141592653589793238462643383279502884;
constexpr double kDeg = kPi / 180.0;   // same value as Swift `Double.pi / 180`
constexpr double kGravity = 9.81;

struct Vec3d {
    double x = 0, y = 0, z = 0;
    constexpr Vec3d() = default;
    constexpr Vec3d(double x_, double y_, double z_) : x(x_), y(y_), z(z_) {}
    static constexpr Vec3d splat(double s) { return {s, s, s}; }
    constexpr Vec3d operator+(const Vec3d& b) const { return {x + b.x, y + b.y, z + b.z}; }
    constexpr Vec3d operator-(const Vec3d& b) const { return {x - b.x, y - b.y, z - b.z}; }
    constexpr Vec3d operator-() const { return {-x, -y, -z}; }
    constexpr Vec3d operator*(double s) const { return {x * s, y * s, z * s}; }
    constexpr Vec3d operator/(double s) const { return {x / s, y / s, z / s}; }   // Swift SIMD / scalar divides each lane
    Vec3d& operator+=(const Vec3d& b) { x += b.x; y += b.y; z += b.z; return *this; }
    Vec3d& operator-=(const Vec3d& b) { x -= b.x; y -= b.y; z -= b.z; return *this; }
    Vec3d& operator*=(double s) { x *= s; y *= s; z *= s; return *this; }
    Vec3d& operator/=(double s) { x /= s; y /= s; z /= s; return *this; }
    constexpr bool operator==(const Vec3d&) const = default;
    double operator[](int i) const { return i == 0 ? x : (i == 1 ? y : z); }
    double& operator[](int i) { return i == 0 ? x : (i == 1 ? y : z); }
};
constexpr Vec3d operator*(double s, const Vec3d& v) { return v * s; }
/// Lane-wise product (Swift `a * b` on SIMD3).
constexpr Vec3d hadamard(const Vec3d& a, const Vec3d& b) { return {a.x * b.x, a.y * b.y, a.z * b.z}; }

constexpr double dot(const Vec3d& a, const Vec3d& b) { return a.x * b.x + a.y * b.y + a.z * b.z; }
constexpr double lengthSquared(const Vec3d& a) { return dot(a, a); }
inline double length(const Vec3d& a) { return std::sqrt(dot(a, a)); }
inline Vec3d normalize(const Vec3d& a) { return a * (1.0 / std::sqrt(dot(a, a))); }
inline Vec3d cross(const Vec3d& a, const Vec3d& b) {
    return {std::fma(a.y, b.z, -(a.z * b.y)), std::fma(a.z, b.x, -(a.x * b.z)), std::fma(a.x, b.y, -(a.y * b.x))};
}
inline Vec3d vmin3(const Vec3d& a, const Vec3d& b) { return {a.x < b.x ? a.x : b.x, a.y < b.y ? a.y : b.y, a.z < b.z ? a.z : b.z}; }
inline Vec3d vmax3(const Vec3d& a, const Vec3d& b) { return {a.x > b.x ? a.x : b.x, a.y > b.y ? a.y : b.y, a.z > b.z ? a.z : b.z}; }

struct Quatd {
    double x = 0, y = 0, z = 0, w = 1;   // vector (imag) part, real part — simd_quatd layout
    static constexpr Quatd identity() { return {0, 0, 0, 1}; }
    /// simd_quaternion(angle, axis): the axis is used as given (NOT normalised), like Swift `Quatd(angle:axis:)`.
    static Quatd angleAxis(double angle, const Vec3d& axis) {
        double s = std::sin(angle / 2);
        return {s * axis.x, s * axis.y, s * axis.z, std::cos(angle / 2)};
    }
    /// Normalises the axis first (convenience; identical to angleAxis for exact unit axes such as {1,0,0}).
    static Quatd axisAngle(double angle, const Vec3d& axis) { return angleAxis(angle, normalize(axis)); }
    /// Euler XYZ in degrees (three.js 'XYZ' order: R = Rx * Ry * Rz), as used by craft JSON `rot`.
    static Quatd eulerXYZDegrees(const Vec3d& e) {
        return angleAxis(e.x * kDeg, {1, 0, 0}) * angleAxis(e.y * kDeg, {0, 1, 0}) * angleAxis(e.z * kDeg, {0, 0, 1});
    }
    Vec3d imag() const { return {x, y, z}; }
    Quatd operator*(const Quatd& q) const {
        const double A[4] = {q.w, -q.z, q.y, -q.x}, B[4] = {q.z, q.w, -q.x, -q.y}, C[4] = {-q.y, q.x, q.w, -q.z};
        const double D[4] = {q.x, q.y, q.z, q.w};
        double r[4];
        for (int i = 0; i < 4; ++i) r[i] = std::fma(x, A[i], y * B[i]) + std::fma(z, C[i], w * D[i]);
        return {r[0], r[1], r[2], r[3]};
    }
    Quatd conjugate() const { return {-x, -y, -z, w}; }
    double lengthSquared() const { return (x * x + z * z) + (y * y + w * w); }   // simd_reduce_add(double4)
    double norm() const { return std::sqrt(lengthSquared()); }
    Quatd normalized() const {
        double l2 = lengthSquared();
        if (l2 == 0) return identity();
        double s = 1 / std::sqrt(l2);
        return {x * s, y * s, z * s, w * s};
    }
    Quatd inverse() const { double s = 1 / lengthSquared(); return {-x * s, -y * s, -z * s, w * s}; }
    /// simd_act on arm64: q * (v * conj(q)), vector part.
    Vec3d act(const Vec3d& v) const {
        Quatd c = conjugate();
        const double A[4] = {c.w, -c.z, c.y, -c.x}, B[4] = {c.z, c.w, -c.x, -c.y}, C[4] = {-c.y, c.x, c.w, -c.z};
        double t[4];
        for (int i = 0; i < 4; ++i) t[i] = std::fma(v.z, C[i], std::fma(v.x, A[i], v.y * B[i]));
        Quatd r = *this * Quatd{t[0], t[1], t[2], t[3]};
        return {r.x, r.y, r.z};
    }
    constexpr bool operator==(const Quatd&) const = default;
};

/// 3x3 double matrix, column-major like simd_double3x3 (c[j] = column j).
struct Mat3d {
    Vec3d c[3] = {{1, 0, 0}, {0, 1, 0}, {0, 0, 1}};
    static Mat3d columns(const Vec3d& a, const Vec3d& b, const Vec3d& d) { Mat3d m; m.c[0] = a; m.c[1] = b; m.c[2] = d; return m; }
    static Mat3d diagonal(const Vec3d& d) { return columns({d.x, 0, 0}, {0, d.y, 0}, {0, 0, d.z}); }
    static Mat3d zero() { return diagonal({0, 0, 0}); }
    /// simd_matrix3x3(quatd)
    static Mat3d fromQuat(const Quatd& q) {
        double x = q.x, y = q.y, z = q.z, w = q.w;
        return columns({std::fma(w, w, std::fma(-z, z, std::fma(x, x, -(y * y)))), 2 * std::fma(x, y, z * w), 2 * std::fma(x, z, -(y * w))},
                       {2 * std::fma(x, y, -(z * w)), std::fma(-x, x, std::fma(w, w, std::fma(y, y, -(z * z)))), 2 * std::fma(y, z, x * w)},
                       {2 * std::fma(z, x, y * w), 2 * std::fma(y, z, -(x * w)), std::fma(-y, y, std::fma(-x, x, std::fma(z, z, w * w)))});
    }
    Vec3d operator*(const Vec3d& v) const {
        Vec3d r = c[0] * v.x;
        r = {std::fma(c[1].x, v.y, r.x), std::fma(c[1].y, v.y, r.y), std::fma(c[1].z, v.y, r.z)};
        r = {std::fma(c[2].x, v.z, r.x), std::fma(c[2].y, v.z, r.y), std::fma(c[2].z, v.z, r.z)};
        return r;
    }
    Mat3d operator*(const Mat3d& b) const { return columns(*this * b.c[0], *this * b.c[1], *this * b.c[2]); }
    Mat3d operator*(double s) const { return columns(c[0] * s, c[1] * s, c[2] * s); }
    Mat3d operator+(const Mat3d& b) const { return columns(c[0] + b.c[0], c[1] + b.c[1], c[2] + b.c[2]); }
    Mat3d operator-(const Mat3d& b) const { return columns(c[0] - b.c[0], c[1] - b.c[1], c[2] - b.c[2]); }
    Mat3d& operator+=(const Mat3d& b) { return *this = *this + b; }
    Mat3d transpose() const { return columns({c[0].x, c[1].x, c[2].x}, {c[0].y, c[1].y, c[2].y}, {c[0].z, c[1].z, c[2].z}); }
    /// simd_inverse (libsystem_m __invert_d3, arm64)
    Mat3d inverse() const {
        const Vec3d &a = c[0], &b = c[1], &d = c[2];
        double r00 = std::fma(b.y, d.z, -(b.z * d.y)), t = std::fma(a.y, d.z, -(a.z * d.y));
        double r01 = std::fma(-a.y, d.z, a.z * d.y), r02 = std::fma(a.y, b.z, -(a.z * b.y));
        double r10 = std::fma(-b.x, d.z, b.z * d.x), r11 = std::fma(a.x, d.z, -(a.z * d.x)), r12 = std::fma(-a.x, b.z, a.z * b.x);
        double r20 = std::fma(b.x, d.y, -(b.y * d.x)), r21 = std::fma(-a.x, d.y, a.y * d.x), r22 = std::fma(a.x, b.y, -(a.y * b.x));
        double det = std::fma(d.x, r02, std::fma(a.x, r00, -(b.x * t)));
        double s = 1 / det;
        return columns({r00 * s, r01 * s, r02 * s}, {r10 * s, r11 * s, r12 * s}, {r20 * s, r21 * s, r22 * s});
    }
    constexpr bool operator==(const Mat3d&) const = default;
};

/// Swift.min / Swift.max exactly (argument order matters for NaN and signed zero).
constexpr double smin(double x, double y) { return y < x ? y : x; }
constexpr double smax(double x, double y) { return y >= x ? y : x; }
/// Swift PWCore `clamp(v, a, b)` = max(a, min(b, v)).
constexpr double clamp(double v, double lo, double hi) { return smax(lo, smin(hi, v)); }
constexpr double smoothstep(double e0, double e1, double x) {
    double t = clamp((x - e0) / (e1 - e0), 0.0, 1.0);
    return t * t * (3.0 - 2.0 * t);
}
constexpr double lerp(double a, double b, double t) { return a + (b - a) * t; }

} // namespace pw
